:root {
  --bg: #0f1115;
  --panel: #1a1d24;
  --panel-2: #23272f;
  --border: #2e333d;
  --text: #e6e8ec;
  --muted: #9aa1ac;
  --accent: #5b8cff;
  --accent-2: #3a6df0;
  --danger: #ff6b6b;
  --radius: 10px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  padding: 1rem 1.5rem;
  background: var(--panel);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 10;
}

.topbar h1 { font-size: 1.25rem; margin: 0; white-space: nowrap; }

.search { flex: 1; max-width: 480px; }
.search input {
  width: 100%;
  padding: 0.6rem 0.9rem;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  background: var(--panel-2);
  color: var(--text);
  font-size: 0.95rem;
}

main {
  display: grid;
  grid-template-columns: 340px 1fr;
  gap: 1.5rem;
  padding: 1.5rem;
  max-width: 1100px;
  margin: 0 auto;
}

@media (max-width: 760px) {
  main { grid-template-columns: 1fr; }
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.25rem;
  height: fit-content;
  position: sticky;
  top: 84px;
}

form h2 { margin: 0 0 1rem; font-size: 1.05rem; }

label {
  display: block;
  font-size: 0.8rem;
  color: var(--muted);
  margin-bottom: 0.8rem;
}

label input, label textarea {
  display: block;
  width: 100%;
  margin-top: 0.3rem;
  padding: 0.55rem 0.7rem;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--panel-2);
  color: var(--text);
  font-size: 0.9rem;
  font-family: inherit;
  resize: vertical;
}

.form-actions { display: flex; gap: 0.6rem; }

button {
  padding: 0.55rem 1.1rem;
  border-radius: 8px;
  border: none;
  background: var(--accent-2);
  color: white;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
}
button:hover { background: var(--accent); }
button.ghost { background: transparent; border: 1px solid var(--border); color: var(--muted); }
button.ghost:hover { color: var(--text); }

.error { color: var(--danger); font-size: 0.85rem; min-height: 1.2em; margin: 0.6rem 0 0; }

.tagcloud {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-top: 1.25rem;
  padding-top: 1.25rem;
  border-top: 1px solid var(--border);
}
.tagcloud:empty { display: none; }

.chip {
  padding: 0.25rem 0.6rem;
  border-radius: 999px;
  background: var(--panel-2);
  border: 1px solid var(--border);
  color: var(--muted);
  font-size: 0.78rem;
  cursor: pointer;
}
.chip:hover { color: var(--text); }
.chip.active { background: var(--accent-2); color: white; border-color: var(--accent-2); }
.chip .c { opacity: 0.6; margin-left: 0.3rem; }

.list-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--muted);
  font-size: 0.85rem;
  margin-bottom: 0.75rem;
}
#activeFilter { color: var(--accent); cursor: pointer; }
#activeFilter:empty { display: none; }

.list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 0.75rem; }

.card {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem 1.15rem;
}
.card a.title {
  color: var(--text);
  font-weight: 600;
  font-size: 1rem;
  text-decoration: none;
}
.card a.title:hover { color: var(--accent); }
.card .url { color: var(--muted); font-size: 0.8rem; word-break: break-all; margin: 0.15rem 0 0; }
.card .desc { margin: 0.5rem 0 0; font-size: 0.9rem; }
.card .meta { display: flex; align-items: center; justify-content: space-between; margin-top: 0.7rem; gap: 0.5rem; }
.card .tags { display: flex; flex-wrap: wrap; gap: 0.35rem; }
.card .actions { display: flex; gap: 0.5rem; flex-shrink: 0; }
.card .actions button {
  padding: 0.3rem 0.6rem;
  font-size: 0.78rem;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--muted);
}
.card .actions button:hover { color: var(--text); }
.card .actions button.del:hover { color: var(--danger); border-color: var(--danger); }

.empty { color: var(--muted); text-align: center; padding: 2rem; }

